sys_variable_value.value:
/*
Created by: Guillaume Houde
Note: the whole reason for the existence of this action is that the option "NOT IN" isn't available in the filter' dropdown for sys_id
 */
(function execute(inputs, outputs) {
    var positionsWithActiveHIRA = [];
    var position;

    while(inputs.activeHiras.next()){
        position = inputs.activeHiras.position_reporting_position; 
        if(position){ //positions should be there but sometimes they're not, so we must check if null/undefined
            if(!gs.nil(position)){
                positionsWithActiveHIRA.push(position.sys_id.toString());
            }else{
                gs.debug('HIRA - "HoC OHSM - HIRA - Lookup Records (No active HIRA)" issue');
            }
        }
    }

    var pos = new GlideRecord('x_hccc_hoc_ohs_position_reports_to');
    //vvv Uncomment when debugging vvv
    //pos.addQuery('reports_to.active', true);
    //pos.addQuery('reports_to.department.business_unit.u_hoc_bu_type', 'admin')
    //^^^ Comment when done ^^^
    pos.addEncodedQuery(inputs.conditions);
    pos.addQuery('sys_id', 'NOT IN', positionsWithActiveHIRA); //This filter is not available when doing a regular lookup records
    pos.query();

    outputs.unprocessed_positions = pos;
})(inputs, outputs);

